const request = $input.first().json;

// Validate required fields
if (!request.client_id || !request.service_name) {
  return [{ json: { allowed: false, error: 'Missing client_id or service_name' } }];
}

// Service-specific rate limits
const serviceLimits = {
  ahrefs: { max_per_hour: 50, max_per_day: 500 },
  hubspot: { max_per_hour: 1000, max_per_day: 10000 },
  sendgrid: { max_per_hour: 500, max_per_day: 5000 },
  google_api: { max_per_hour: 100, max_per_day: 1000 },
  slack: { max_per_hour: 100, max_per_day: 2000 }
};

const limits = serviceLimits[request.service_name] || { max_per_hour: 100, max_per_day: 1000 };

return [{
  json: {
    client_id: request.client_id,
    service_name: request.service_name,
    max_per_hour: limits.max_per_hour,
    max_per_day: limits.max_per_day,
    action: request.action || 'check' // check or consume
  }
}];

const rateResult = $input.first().json;
const request = $node['Parse Rate Request'].json;

const hourlyAllowed = rateResult.allowed_hourly === true;
const dailyUsage = parseInt(rateResult.daily_usage) || 0;
const dailyAllowed = dailyUsage < request.max_per_day;

const allowed = hourlyAllowed && dailyAllowed;

let retryAfter = null;
if (!hourlyAllowed) {
  // Calculate seconds until next hour window
  const now = new Date();
  const nextHour = new Date(now);
  nextHour.setHours(nextHour.getHours() + 1, 0, 0, 0);
  retryAfter = Math.ceil((nextHour - now) / 1000);
}

return [{
  json: {
    allowed: allowed,
    client_id: request.client_id,
    service_name: request.service_name,
    hourly_allowed: hourlyAllowed,
    daily_allowed: dailyAllowed,
    daily_usage: dailyUsage,
    daily_limit: request.max_per_day,
    hourly_limit: request.max_per_hour,
    retry_after_seconds: retryAfter,
    remaining_daily: Math.max(0, request.max_per_day - dailyUsage)
  }
}];
